a = {1, 2, 3, 4}
b = {3, 4, 5, 6}

print(a | b)   # unión: {1, 2, 3, 4, 5, 6}
print(a & b)   # intersección: {3, 4}
print(a - b)   # diferencia: {1, 2}
print(a ^ b)   # diferencia simétrica: {1, 2, 5, 6}

persona = {"nombre": "Ana"}

persona["edad"] = 25          # agregar
persona["nombre"] = "Ana María"   # modificar

del persona["edad"]           # eliminar

print(persona)   # {'nombre': 'Ana María'}

persona = {"nombre": "Ana", "edad": 25, "ciudad": "Madrid"}

# Claves
for k in persona:
    print(k)

# Valores
for v in persona.values():
    print(v)

# Pares
for k, v in persona.items():
    print(f"{k}: {v}")

texto = "hola mundo hola python hola"
palabras = texto.split()

conteo = {}
for p in palabras:
    conteo[p] = conteo.get(p, 0) + 1

print(conteo)
# {'hola': 3, 'mundo': 1, 'python': 1}

conteo = {}

conteo.setdefault("a", []).append(1)
conteo.setdefault("a", []).append(2)
conteo.setdefault("b", []).append(10)

print(conteo)   # {'a': [1, 2], 'b': [10]}

d = {"a": 1, "b": 2, "c": 3}

valor = d.pop("b")
print(valor)   # 2
print(d)       # {'a': 1, 'c': 3}

par = d.popitem()
print(par)     # ('c', 3)
print(d)       # {'a': 1}

