ejemplos.codigo:
cuadrados_unicos = {x**2 for x in [1, 1, 2, 2, 3, 3]}
print(cuadrados_unicos)   # {1, 4, 9}

letras = {c.lower() for c in "Hola Mundo" if c.isalpha()}
print(letras)   # {'h', 'o', 'l', 'a', 'm', 'u', 'n', 'd'}

numeros = [1, 2, 3, 4]
cuadrados = {x: x**2 for x in numeros}
print(cuadrados)   # {1: 1, 2: 4, 3: 9, 4: 16}

original = {"a": 1, "b": 2, "c": 3}
invertido = {v: k for k, v in original.items()}
print(invertido)   # {1: 'a', 2: 'b', 3: 'c'}

edades = {"Ana": 25, "Luis": 17, "Eva": 30, "Pedro": 15}

mayores = {n: e for n, e in edades.items() if e >= 18}
print(mayores)   # {'Ana': 25, 'Eva': 30}
